const americanConstitutionLandscape={src:"assets/diagrams/american-constitutional-order.svg",alt:"Diagram of the constitutional order of the forty-eight-state United States",caption:"The Constitution separates presidency, bicameral Congress, and federal courts while states control extensive domestic law and much election machinery"};
